function closeCardLayers(){for(const dialog of [...document.querySelectorAll('dialog[open]')].reverse())dialog.close();}
function showCard(id,grade=null,scope='set'){
 const c=byId.get(id);if(!c)return;grade??=0;const database=view==='database',variants=state.cards.filter(v=>v.baseId===c.baseId&&[0,1,2,7].includes(v.expansion)&&(scope==='all'||v.setId===c.setId)),gp=c.gradePrices[grade-1],price=grade?gp?.price:c.price,history=grade?gp?.history||[]:c.history,owned=grade?c.grades.filter(g=>g.grade===grade).length:c.ungradedOwned;
 openModal(`<div class="modal-head"><div><div class="eyebrow">CARD DETAILS</div><h2>${esc(c.name)}</h2></div><button data-close aria-label="Close card details">✕</button></div><div class="modal-body"><div class="detail-art">${grade?`<div class="grade-label"><strong>PSA ${grade}</strong><span>${esc(c.name)} · ${esc(c.variant)}</span></div>`:''}${visual(c)}<p class="subtle">Art / studio: ${esc(c.artist)}<br>${esc(c.set)} · ${esc(c.rarity)} · Card page ${c.cardNumber}<br>${esc(c.variant)} · #${c.number}</p>${grade?'<p class="notice">Graded copies cannot be used in decks.</p>':modal.dataset.variantPreview?'<p class="subtle">Close card details to continue assigning variants.</p>':view==='decks'&&editing?`<div class="detail-add-controls"><button class="primary" id="detail-add" ${deckCount(c.baseId)>=4||totalCards(selectedDeck)>=50?'disabled':''}>+ Add to deck</button><output id="detail-deck-count" aria-live="polite" aria-label="Copies of ${esc(c.name)} in deck">${deckCount(c.baseId)} / 4 <small>in deck</small></output></div>`:'<button id="detail-build">Build a deck with this card</button>'}</div><div>${evolutionLinks(c)}<p class="detail-description">${esc(c.description)}</p><div class="element-stats">${Object.entries(c.stats).map(([k,v])=>{const name=k.replace('Element','');return `<span><img src="${renderData.icons[name.toLowerCase()]}" alt="${name}" title="${name}"><strong>${v}</strong></span>`;}).join('')}</div><label class="grade-control">Condition / grade <select id="grade-select"><option value="0">Ungraded${database?'':` · ${c.ungradedOwned} owned`}</option>${c.gradePrices.map(g=>`<option value="${g.grade}" ${grade===g.grade?'selected':''}>PSA ${g.grade}${database?'':` · ${c.grades.filter(x=>x.grade===g.grade).length} owned`}</option>`).join('')}</select></label><div class="detail-stats"><div class="detail-stat"><small>${grade?'Graded':'Market'} price</small><strong>${price==null?'Unavailable':money(price)}</strong>${grade&&price!=null?`<span class="price-delta ${price<c.price?'negative':'positive'}">${price>=c.price?'+':'−'}${money(Math.abs(price-c.price))} vs ungraded / card</span>`:''}</div>${database?'':`<div class="detail-stat"><small>Available / owned</small>${availableOwnedUI(c,grade)}</div><div class="detail-stat"><small>Owned ${grade?`PSA ${grade}`:'ungraded'} total value</small><strong>${price==null?'Unavailable':money(owned*price)}</strong></div>`}<div class="detail-stat"><small>Estimated ${grade?'regraded':'graded'} value / copy</small>${gradingEstimateUI(c,grade)}</div></div>${database?'':`<p class="subtle">Locations: ${esc(locationText(c,grade))}<br>All conditions: ${c.owned} copies · ${money(c.value)} total</p>`}<h3>Market history${grade?` · PSA ${grade}`:''}</h3>${chart(history.filter(v=>v!=null))}<p class="subtle">${history.length} days of saved market prices. Graded prices use the game’s grade multipliers and bonuses.</p><h3>Explore variants &amp; grades</h3><label class="grade-control">Show <select id="variant-scope"><option value="set" ${scope==='set'?'selected':''}>Variants in this set</option><option value="all" ${scope==='all'?'selected':''}>All sets &amp; Ghost variants</option><option value="grades" ${scope==='grades'?'selected':''}>PSA grades of this exact variant</option></select></label><div class="table-scroll"><table class="detail-table"><thead><tr><th>${scope==='grades'?'Condition':'Variant'}</th>${database?'':'<th>Available</th><th>Ungraded owned</th><th>Graded owned</th>'}<th>Price</th></tr></thead><tbody>${scope==='grades'?[0,...c.gradePrices.map(g=>g.grade)].map(g=>`<tr><td><button data-detail-grade="${g}">${g?'PSA '+g:'Ungraded'}</button></td>${database?'':`<td>${g?'—':num(c.available)}</td><td title="${esc(locationText(c,0))}">${g?'—':num(c.ungradedOwned)}</td><td title="${esc(locationText(c,g||'all'))}">${g?num(c.grades.filter(x=>x.grade===g).length):'—'}</td>`}<td>${money(g?c.gradePrices[g-1]?.price:c.price)}</td></tr>`).join(''):variants.map(v=>`<tr class="${v.id===id?'current':''}"><td><button data-detail-variant="${v.id}">${esc(v.set)} · ${esc(v.variant)}</button></td>${database?'':`<td title="${esc(v.available+' album copies')}">${v.available}</td><td title="${esc(locationText(v,0))}">${v.ungradedOwned}</td><td title="${esc(locationText(v,'all'))}">${v.gradedCount}</td>`}<td>${money(grade?v.gradePrices[grade-1]?.price:v.price)}</td></tr>`).join('')}</tbody></table></div></div></div>`);
 modal.scrollTop=0;$('#grade-select').onchange=e=>showCard(id,+e.target.value,scope);$('#variant-scope').onchange=e=>showCard(id,grade,e.target.value);modal.querySelectorAll('[data-detail-grade]').forEach(b=>b.onclick=()=>showCard(id,Number(b.dataset.detailGrade),scope));modal.querySelectorAll('[data-evolution-card]').forEach(b=>b.onclick=()=>showCard(b.dataset.evolutionCard,grade,scope));modal.querySelectorAll('[data-detail-variant]').forEach(b=>b.onclick=()=>showCard(b.dataset.detailVariant,grade,scope));if($('#detail-add'))$('#detail-add').onclick=()=>{const before=deckCount(c.baseId);addCard(c.id);const count=deckCount(c.baseId);$('#detail-deck-count').innerHTML=`${count} / 4 <small>in deck</small>`;$('#detail-add').disabled=count>=4||totalCards(selectedDeck)>=50;if(count>before)toast('Card added to draft');};if($('#detail-build'))$('#detail-build').onclick=()=>{closeCardLayers();startDeck();addCard(c.id);};
}

function showAllocation(base){
 const card=state.cards.find(c=>c.baseId===base),originalTotal=deckCount(base),limit=Math.min(4,50-totalCards(selectedDeck)+originalTotal),all=state.cards.filter(c=>c.baseId===base&&[0,1,2,7].includes(c.expansion)).sort((a,b)=>[0,1,7,2].indexOf(a.expansion)-[0,1,7,2].indexOf(b.expansion)||a.setId.localeCompare(b.setId)||a.saveIndex-b.saveIndex),counts=new Map(selectedDeck.entries.filter(e=>byId.get(e.cardId)?.baseId===base).map(e=>[e.cardId,e.amount]));
 let total=originalTotal,set='';const assigned=()=>[...counts.values()].reduce((n,v)=>n+v,0);
 function paint(){openModal(`<div class="modal-head"><div><h2>${esc(card.name)} · choose variants</h2><p class="subtitle">Assign ${total} ${total===1?'copy':'copies'}. Ungraded album and intended-replacement copies are usable. Unowned choices may still be drafted.</p></div><button data-close aria-label="Close variant selector">✕</button></div><div class="modal-simple"><div class="variant-toolbar"><label>Pack <select id="allocation-set"><option value="">All packs</option>${state.sets.filter(s=>[0,1,2,7].includes(s.expansion)).map(s=>`<option value="${s.id}" ${set===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><div class="allocation-count"><span>Copies in deck</span><div class="counter"><button id="allocation-count-minus" aria-label="Decrease copies in deck" ${total===0?'disabled':''}>−</button><strong>${total}</strong><button id="allocation-count-plus" aria-label="Increase copies in deck" ${total>=limit?'disabled':''}>+</button></div><small aria-live="polite">${assigned()} / ${total} assigned · ${totalCards(selectedDeck)-originalTotal+total} / 50 deck</small></div><div class="auto-assign-controls"><select id="variant-auto-mode" aria-label="Automatic variant strategy"><option value="quantity" ${allocationMode==='quantity'?'selected':''}>Most quantity</option><option value="cheapest" ${allocationMode==='cheapest'?'selected':''}>Least expensive</option><option value="expensive" ${allocationMode==='expensive'?'selected':''}>Most expensive usable</option></select><button id="cheapest">Auto-assign variants</button></div></div><div class="variant-gallery">${all.filter(v=>!set||v.setId===set).map(v=>{const count=counts.get(v.id)||0;return `<article class="variant-choice ${count?'selected':''}"><button class="variant-preview" data-preview-variant="${v.id}" aria-label="View ${esc(v.set+' '+v.name+' '+v.variant)}">${visual(v)}</button><strong>${esc(v.set)}</strong><span>${esc(v.variant)}</span><div class="variant-availability"><strong class="variant-usable ${usableCopies(v,selectedDeck,state.decks)>0?'has-copies':'no-copies'}">${num(usableCopies(v,selectedDeck,state.decks))} usable</strong><span>${num(v.inDeck)} in decks · ${num(v.elsewhere)} stored · ${num(v.gradedCount)} graded</span></div><div class="counter"><button data-variant-minus="${v.id}" ${!count?'disabled':''} aria-label="Use one fewer ${esc(v.set+' '+v.variant)}">−</button><output>${count}</output><button data-variant-plus="${v.id}" ${assigned()>=total||count>=4?'disabled':''} aria-label="Use one more ${esc(v.set+' '+v.variant)}">+</button></div><div class="variant-shortage-slot" aria-live="polite">${count>usableCopies(v,selectedDeck,state.decks)?`<span class="inventory-issue shortage static-shortage">${count-usableCopies(v,selectedDeck,state.decks)} unavailable</span>`:''}</div></article>`;}).join('')}</div><div class="allocation-footer"><p class="subtle">All variants are shown, even with zero copies. Red marks flag shortages; selected variants are never silently changed. Auto-assign uses usable owned copies first, then a flagged draft placeholder only if needed.</p><div class="allocation-buttons"><button id="deselect-variants" ${!assigned()?'disabled':''}>Deselect all variants</button><button class="primary" id="apply-allocation" ${assigned()!==total?'disabled':''}>Apply variants</button></div></div></div>`);
 modal.classList.add('wide-variants');$('#allocation-count-plus').onclick=()=>{if(total<limit){total++;paint();}};$('#allocation-count-minus').onclick=()=>{if(!total)return;total--;for(const [id,n] of [...counts].reverse()){if(assigned()<=total)break;counts.set(id,Math.max(0,n-(assigned()-total)));}paint();};modal.querySelectorAll('[data-preview-variant]').forEach(b=>b.onclick=()=>showCardAboveModal(b.dataset.previewVariant));$('#deselect-variants').onclick=()=>{counts.clear();paint();};modal.querySelectorAll('[data-allocation-issue]').forEach(b=>b.onclick=()=>showCopyIssue(b.dataset.allocationIssue,'',counts.get(b.dataset.allocationIssue)||0,paint));$('#variant-auto-mode').onchange=e=>allocationMode=e.target.value;
 $('#allocation-set').onchange=e=>{set=e.target.value;paint();};modal.querySelectorAll('[data-variant-minus]').forEach(b=>b.onclick=()=>{counts.set(b.dataset.variantMinus,Math.max(0,(counts.get(b.dataset.variantMinus)||0)-1));paint();});modal.querySelectorAll('[data-variant-plus]').forEach(b=>b.onclick=()=>{if(assigned()<total)counts.set(b.dataset.variantPlus,(counts.get(b.dataset.variantPlus)||0)+1);paint();});$('#cheapest').onclick=()=>{counts.clear();for(const e of allocate(all.map(v=>({...v,available:usableCopies(v,selectedDeck,state.decks)})),base,total,set||card.setId,allocationMode))counts.set(e.cardId,e.amount);paint();};$('#apply-allocation').onclick=()=>{if(assigned()!==total)return;selectedDeck.entries=selectedDeck.entries.filter(e=>byId.get(e.cardId)?.baseId!==base).concat([...counts].filter(([,amount])=>amount>0).map(([cardId,amount])=>({cardId,amount})));selectedDeck.coverCardIds=(selectedDeck.coverCardIds||[]).filter(id=>selectedDeck.entries.some(e=>e.cardId===id));dirty=true;modal.close();refreshDeck();};
 }paint();
}
function confirmDeleteDraft(id){const d=state.drafts.find(x=>x.id===id);if(!d)return;openModal(`<div class="modal-head"><h2>Delete ${esc(d.name)}?</h2><button data-close>Cancel</button></div><div class="modal-simple"><p>This deletes the local draft and its W–L record. Your in-game decks and cards are unchanged.</p><button class="danger" id="confirm-delete-draft">Delete draft</button></div>`);$('#confirm-delete-draft').onclick=async()=>{try{accept(await api('/drafts/'+id,'DELETE'));modal.close();if(selectedDeck?.id===id){selectedDeck=null;editing=false;dirty=false;}render();toast('Draft deleted');}catch(e){toast(e.message);}};}
function editRecord(id){const d=findDeck(id);openModal(`<div class="modal-head"><h2>${esc(d.name)} · manual W–L</h2><button data-close>Close</button></div><div class="modal-simple"><p>Results follow this local build through edits. Recording results for an unbacked game deck creates its local backup.</p><div class="record-fields"><label class="wins">Wins <input id="record-wins" type="number" min="0" max="999999" step="1" value="${d.record?.wins||0}"></label><label class="losses">Losses <input id="record-losses" type="number" min="0" max="999999" step="1" value="${d.record?.losses||0}"></label></div><button class="primary" id="save-record">Save record</button></div>`);modal.classList.add('compact-record');$('#save-record').onclick=async()=>{try{accept(await api('/deck-record','POST',{deckId:id,record:{wins:Number($('#record-wins').value),losses:Number($('#record-losses').value)}}));modal.close();render();toast('Manual record saved');}catch(e){toast(e.message);}};}
function viewDeck(id,collapsed=false){const d=findDeck(id),backup=state.drafts.find(x=>x.gameId===d.id),entries=collapsed?collapsedDeckEntries(d.entries,state.cards):d.entries;openModal(`<div class="modal-head"><div><h2>${esc(d.name)}</h2><p class="subtitle">${totalCards(d)} / 50 cards · ${money(deckValue(d))}${d.source==='game'?` · ${backup?'Local backup saved':'No local backup'}`:''}</p></div><button data-close>✕</button></div><div class="modal-simple"><div class="deck-gallery-toolbar"><button id="collapse-deck-variants" aria-pressed="${collapsed}">${collapsed?'Expand variants':'Collapse variants'}</button><span class="subtle">${collapsed?'Combined counts · highest-value selected variant shown':'Exact variants selected for this deck'}</span></div><div class="card-grid deck-gallery">${entries.map(e=>{const c=byId.get(e.cardId);return c?`<div class="card-tile"><button class="card-open" data-deck-card="${c.id}">${visual(c,false)}</button><div class="card-info"><div><strong>${e.amount} × ${esc(c.name)}</strong><small>${esc(c.set)} · ${esc(c.variant)}</small></div><span>${money(collapsed?d.entries.filter(x=>byId.get(x.cardId)?.baseId===c.baseId).reduce((n,x)=>n+(byId.get(x.cardId)?.price||0)*x.amount,0):c.price*e.amount)}</span></div></div>`:'';}).join('')}</div><div class="deck-actions"><button id="modal-edit">${d.source==='game'?'Edit as draft':'Edit draft'}</button>${d.source!=='game'?'<button id="modal-export">Export deck</button><button class="danger" id="delete-draft">Delete draft</button>':backup?'<span class="backup-status backed-up">✓ Local backup saved</span>':'<button id="backup-deck">Keep a local draft backup</button>'}</div></div>`);modal.classList.add('wide-deck');$('#collapse-deck-variants').onclick=()=>viewDeck(id,!collapsed);modal.querySelectorAll('[data-deck-card]').forEach(b=>b.onclick=()=>showCardAboveModal(b.dataset.deckCard));$('#modal-edit').onclick=()=>{modal.close();startDeck(d);};if($('#modal-export'))$('#modal-export').onclick=()=>exportDraft(d.id);if($('#delete-draft'))$('#delete-draft').onclick=()=>confirmDeleteDraft(d.id);if($('#backup-deck'))$('#backup-deck').onclick=async()=>{try{accept(await api('/drafts','POST',{name:d.name,entries:d.entries,coverCardIds:d.coverCardIds||[]}));modal.close();render();toast('Local backup saved; it will become a draft if removed from the game');}catch(e){toast(e.message);}};}
async function exportDraft(id){try{const d=findDeck(id);if(!d)throw Error('Deck not found.');const text=d.source==='game'?exportDeck(d,state.cards):(await api(`/drafts/${id}/export`,'POST')).text;openModal(`<div class="modal-head"><div><h2>Ready for the game</h2><p class="subtitle">${esc(d?.name||'Deck')} · ${totalCards(d)} / 50 cards</p></div><button data-close>✕</button></div><div class="modal-simple"><p class="notice">${totalCards(d)!==50?'This deck is incomplete. Finish it to 50 cards before playing. ':''}Copy this text and use the game’s deck import. Resync after saving to confirm the deck is in game. The game may substitute variants when copies are unavailable.</p><textarea class="export-text" id="export-text" readonly aria-label="Game deck code">${esc(text)}</textarea><div class="deck-actions"><button class="primary" id="copy-code">Copy deck code</button></div></div>`);$('#copy-code').onclick=async()=>{try{await navigator.clipboard.writeText(text);toast('Deck code copied');}catch{$('#export-text').select();toast('Select the text and press Ctrl+C to copy.');}};accept(await api('/state'));render();}catch(e){toast(e.message);}}
function displayCoveragePanel(){return `<section class="chart-panel display-coverage"><details><summary>Supported card displays · all ${(state.displayCoverage||[]).length} types checked on every sync</summary><p class="subtle">Every card in these save records is included, even when the furniture is boxed. An absent display shows zero; it is still supported. Ordinary play tables hold accessories and are not another copy of your deck.</p><div class="table-scroll"><table class="detail-table"><thead><tr><th>Display type</th><th>Total displays</th><th>Cards held</th></tr></thead><tbody>${(state.displayCoverage||[]).map(x=>`<tr><td>${esc(x.name)}</td><td>${num(x.fixtures)}</td><td>${num(x.copies)}</td></tr>`).join('')}</tbody></table></div></details></section>`;}
