 const all=snapshotSeries(state.snapshots,key),requested=syncRanges[key],range=requested==='all'?[all[0]?.x??0,all.at(-1)?.x??1]:requested||recentSyncRange(all,Math.min(700,Math.max(250,(document.documentElement.clientWidth-300)/2))),points=all.filter(p=>p.x>=range[0]&&p.x<=range[1]);
